const os = require('os');
const P = (l, f) => { try { console.log(l, JSON.stringify(f())); } catch (e) { console.log(l, 'throws', e.code, e.name, e.message.slice(0, 120)); } };
P('keys', () => Object.keys(os).sort());
P('types', () => ['arch', 'availableParallelism', 'cpus', 'endianness', 'freemem', 'getPriority', 'homedir', 'hostname', 'loadavg', 'machine', 'networkInterfaces', 'platform', 'release', 'setPriority', 'tmpdir', 'totalmem', 'type', 'uptime', 'userInfo', 'version'].map((k) => `${k}:${typeof os[k]}`));
P('EOL devNull', () => [os.EOL, os.devNull, os.endianness()]);
P('constants keys', () => [Object.keys(os.constants).sort(), Object.keys(os.constants.signals).length >= 30, os.constants.signals.SIGTERM, os.constants.errno.ENOENT, os.constants.priority.PRIORITY_LOW, os.constants.dlopen && typeof os.constants.dlopen.RTLD_NOW]);
P('userInfo shape', () => Object.keys(os.userInfo()).sort());
P('userInfo buffer', () => Buffer.isBuffer(os.userInfo({ encoding: 'buffer' }).username));
P('loadavg shape', () => os.loadavg().length);
P('ni loopback', () => { const ni = os.networkInterfaces(); const lo = Object.values(ni).flat().find((x) => x.internal && x.family === 'IPv4'); return lo && [lo.address, lo.netmask, lo.family, lo.internal, lo.cidr]; });
P('getPriority self', () => typeof os.getPriority());
P('getPriority other', () => os.getPriority(999999));
P('setPriority bad', () => os.setPriority(0, 100));
P('setPriority other', () => os.setPriority(999999, 0));
P('tmpdir', () => typeof os.tmpdir());
